/**
 * The synthetic plugin packages of the plugins suite, generated by the benchmark and holding nothing personal. Each is a
 * dependency-free profile bundle, as upstream's own installation acceptance writes one: a manifest whose `dsh.bundle`
 * names a patch file, a patch that inserts one row whose module is the package's `index.mjs`, and that module, whose
 * row reports on standard output when it starts and stops, with the `generation` its row configuration names. The
 * Host's standard output becomes home-log records, so a suite reads from the home log when a row started or stopped.
 * A package is written as an npm-style tarball (`package/` entries, a fixed modification time, gzip), byte for byte
 * the same for the same index, because pnpm installs a local tarball offline by copying it into the profile, where a
 * local directory would be linked from outside the home.
 *
 * Installing runs `delorun plugin`, which runs the `pnpm` it finds on `PATH`. The suite puts a `pnpm` first on `PATH`
 * that runs the pnpm the runtime closure carries with the closure's own Node, so the install does not depend on a
 * pnpm of the machine.
 *
 * @module @delorun/benchmarks/suites/plugins/packages
 */
import { gzipSync } from 'node:zlib'

/** The text every row's report starts with. */
const EVENT_PREFIX = 'delorun-benchmark-plugin'

/** A row's report in a home-log message: its index, what happened and its configuration's generation. */
const EVENT_PATTERN = /delorun-benchmark-plugin (\d+) (started|stopped) (\d+)/gu

/** The modification time of every tarball entry: the fixed time `npm pack` writes, 1985-10-26T08:15:00Z. */
const TARBALL_MTIME = 499_162_500

/** A tar block. */
const BLOCK = 512

/** One report of a synthetic row. */
export interface PluginEvent {
  /** The plugin's index. */
  readonly index: number
  /** What happened. */
  readonly event: 'started' | 'stopped'
  /** The `generation` of the row's configuration; 1 when it names none. */
  readonly generation: number
  /** When the home log recorded it, in epoch milliseconds. */
  readonly at: number
}

/**
 * The two-digit form of an index.
 * @param index - the index.
 * @returns the index padded to two digits.
 */
function padded(index: number): string {
  return String(index).padStart(2, '0')
}

/**
 * The package name of the synthetic plugin at an index; distinct from the manifest-only packages of `fixtures/data.ts`.
 * @param index - the index.
 * @returns `@delorun-benchmark/loaded-plugin-<nn>`.
 */
export function loadedPluginName(index: number): string {
  return `@delorun-benchmark/loaded-plugin-${padded(index)}`
}

/**
 * The id of the row the synthetic plugin at an index inserts, which a profile patch row names to disable or configure it.
 * @param index - the index.
 * @returns `delorun-benchmark-plugin-<nn>`.
 */
export function loadedPluginRowId(index: number): string {
  return `${EVENT_PREFIX}-${padded(index)}`
}

/**
 * The tarball file name of the synthetic plugin at an index.
 * @param index - the index.
 * @returns `delorun-benchmark-loaded-plugin-<nn>-1.0.0.tgz`, as `npm pack` names a scoped package.
 */
export function loadedPluginTarballName(index: number): string {
  return `delorun-benchmark-loaded-plugin-${padded(index)}-1.0.0.tgz`
}

/**
 * The files of the synthetic plugin at an index.
 * @param index - the index.
 * @returns each file's package-relative path and text, in name order.
 */
export function loadedPluginFiles(index: number): Readonly<Record<string, string>> {
  const id = loadedPluginRowId(index)
  const manifest = {
    name: loadedPluginName(index),
    version: '1.0.0',
    description: 'A synthetic plugin of the Delorun benchmark: one row that reports its start and stop.',
    license: 'MIT',
    type: 'module',
    dsh: { bundle: { patch: './cordis.patch.yml' } },
  }
  return {
    'cordis.patch.yml': `- insert:\n    - id: ${id}\n      name: ./index.mjs\n`,
    'index.mjs': [
      `export const name = '${id}'`,
      'export function apply(ctx, config) {',
      '  const generation = String(config?.generation ?? 1)',
      '  ctx.effect(() => {',
      `    process.stdout.write(\`${EVENT_PREFIX} ${padded(index)} started \${generation}\\n\`)`,
      `    return () => { process.stdout.write(\`${EVENT_PREFIX} ${padded(index)} stopped \${generation}\\n\`) }`,
      '  })',
      '}',
      '',
    ].join('\n'),
    'package.json': `${JSON.stringify(manifest, undefined, 2)}\n`,
  }
}

/**
 * Write a text into a tar header field, NUL-padded.
 * @param header - the header.
 * @param offset - the field's offset.
 * @param text - the text, which fits the field.
 */
function field(header: Buffer, offset: number, text: string): void {
  header.write(text, offset, 'utf8')
}

/**
 * A number as a tar header's octal field: zero-padded to `width - 1` digits and a NUL.
 * @param value - the number.
 * @param width - the field's width.
 * @returns the field's text.
 */
function octal(value: number, width: number): string {
  return `${value.toString(8).padStart(width - 1, '0')}\0`
}

/**
 * A gzip-compressed ustar archive of files under `package/`, as `npm pack` lays a package out, with every entry owned by
 * user 0, mode 0644 and {@link TARBALL_MTIME}, in name order.
 * @param files - each file's package-relative path and text.
 * @returns the archive's bytes.
 * @throws {Error} when an entry's path is longer than a ustar name field holds.
 */
export function packageTarball(files: Readonly<Record<string, string>>): Buffer {
  const blocks: Buffer[] = []
  for (const path of Object.keys(files).sort()) {
    const name = `package/${path}`
    if (Buffer.byteLength(name) > 100) throw new Error(`the tarball entry ${name} is longer than 100 bytes`)
    const content = Buffer.from(files[path]!, 'utf8')
    const header = Buffer.alloc(BLOCK)
    field(header, 0, name)
    field(header, 100, octal(0o644, 8))
    field(header, 108, octal(0, 8))
    field(header, 116, octal(0, 8))
    field(header, 124, octal(content.length, 12))
    field(header, 136, octal(TARBALL_MTIME, 12))
    field(header, 148, ' '.repeat(8))
    field(header, 156, '0')
    field(header, 257, 'ustar\0')
    field(header, 263, '00')
    const sum = header.reduce((total, byte) => total + byte, 0)
    field(header, 148, `${sum.toString(8).padStart(6, '0')}\0 `)
    blocks.push(header, content, Buffer.alloc((BLOCK - content.length % BLOCK) % BLOCK))
  }
  blocks.push(Buffer.alloc(2 * BLOCK))
  return gzipSync(Buffer.concat(blocks), { level: 9 })
}

/**
 * The reports of synthetic rows in a home-log message.
 * @param message - the record's message.
 * @param at - when the record was written, in epoch milliseconds.
 * @returns each report, in message order.
 */
export function pluginEventsIn(message: string, at: number): readonly PluginEvent[] {
  return [...message.matchAll(EVENT_PATTERN)].map(match => ({
    index: Number(match[1]),
    event: match[2] as PluginEvent['event'],
    generation: Number(match[3]),
    at,
  }))
}

/**
 * When every one of the first `count` synthetic rows had started with a generation.
 * @param events - the reports, in any order.
 * @param count - how many rows; indexes `0` to `count - 1`.
 * @param generation - the generation.
 * @returns the time of the last first start, or `undefined` while a row has not started.
 */
export function allStarted(events: readonly PluginEvent[], count: number, generation = 1): number | undefined {
  let last = 0
  for (let index = 0; index < count; index++) {
    const first = events.filter(event => event.index === index && event.event === 'started' && event.generation === generation)
      .reduce((earliest, event) => Math.min(earliest, event.at), Number.POSITIVE_INFINITY)
    if (first === Number.POSITIVE_INFINITY) return undefined
    last = Math.max(last, first)
  }
  return last
}

/**
 * The first report of one row matching an event and generation.
 * @param events - the reports, in any order.
 * @param index - the row's plugin index.
 * @param event - what happened.
 * @param generation - the generation.
 * @returns its time, or `undefined` when there is none.
 */
export function firstEvent(events: readonly PluginEvent[], index: number, event: PluginEvent['event'], generation: number): number | undefined {
  const found = events.filter(candidate => candidate.index === index && candidate.event === event && candidate.generation === generation)
  return found.length === 0 ? undefined : Math.min(...found.map(candidate => candidate.at))
}

/**
 * A profile patch row that disables a row, as the studio's plugin manager writes it to turn a plugin off.
 * @param id - the row's id.
 * @returns the patch row's YAML, one sequence item.
 */
export function disabledOverride(id: string): string {
  return `- id: ${id}\n  disabled: true\n`
}

/**
 * A profile patch row that changes a row's configuration, which restarts the row with the new configuration.
 * @param id - the row's id.
 * @param generation - the configuration's generation.
 * @returns the patch row's YAML, one sequence item.
 */
export function configOverride(id: string, generation: number): string {
  return `- id: ${id}\n  config:\n    generation: ${String(generation)}\n`
}

/**
 * A profile patch's text with patch rows appended.
 * @param original - the patch's text.
 * @param rows - the rows' YAML.
 * @returns the text, with a line end before the rows when the original lacks one.
 */
export function withRows(original: string, rows: string): string {
  return original === '' || original.endsWith('\n') ? `${original}${rows}` : `${original}\n${rows}`
}

/**
 * The package-relative entry of pnpm's command line in its manifest.
 * @param manifest - pnpm's parsed `package.json`.
 * @returns the `pnpm` bin's path.
 * @throws {Error} when the manifest names no `pnpm` bin.
 */
export function pnpmEntry(manifest: unknown): string {
  const bin = typeof manifest === 'object' && manifest !== null ? (manifest as { bin?: unknown }).bin : undefined
  const entry = typeof bin === 'string' ? bin : typeof bin === 'object' && bin !== null ? (bin as Record<string, unknown>)['pnpm'] : undefined
  if (typeof entry !== 'string' || entry === '') throw new Error('the closure\'s pnpm manifest names no pnpm bin')
  return entry
}

/**
 * Quote a text for a POSIX shell.
 * @param text - the text.
 * @returns it in single quotes.
 */
function shellQuoted(text: string): string {
  return `'${text.split('\'').join('\'\\\'\'')}'`
}

/**
 * The `pnpm` script that runs a closure's pnpm with the closure's Node.
 * @param node - the closure's Node executable.
 * @param entry - the absolute path of pnpm's command-line entry.
 * @returns the script's text.
 */
export function pnpmShim(node: string, entry: string): string {
  return `#!/bin/sh\nexec ${shellQuoted(node)} ${shellQuoted(entry)} "$@"\n`
}
